def stock_report(self) -> Dict[str, int]:
    """Return a mapping of SKU to available quantity."""
    report: Dict[str, int] = {}
    keys = set(self._ledger._on_hand.keys()) | set(self._ledger._reserved.keys())
    for sku in keys:
        report[sku] = self._ledger.available(sku)
    return report
